// DAVFX Getting Started
// Editor only. Goes in Assets/DAVFX/Getting Started together with its .meta files.

#if UNITY_EDITOR
namespace DAVFX.GettingStarted
{
    // usings inside the namespace so user types named Path, Color, etc. can't clash
    using System;
    using System.Collections.Generic;
    using System.IO;
    using System.Text.RegularExpressions;
    using UnityEditor;
    using UnityEditor.SceneManagement;
    using UnityEngine;

    public class PackScene
    {
        public string label;
        public string path;
        public string pipeline;
    }

    public class PackEntry
    {
        public string id;
        public string name;
        public string folder;
        public string folderGuid;
        public string docPath;
        public string reviewUrl;
        public string fabUrl;
        public string hdrpPackage;
        public bool hdrpImported;
        public bool isEmpty;
        public readonly List<PackScene> scenes = new List<PackScene>();
    }

    public static class PackRegistry
    {
        public const int MaxScenes = 8;
        public const string DefaultRoot = "Assets/DAVFX";
        public const string ToolFolderName = "Getting Started";
        public const string ScriptGuid = "544dc91bfeba41faad7701ac93b3deb0";
        public static string RootOverride = null; // used by the tests
        private static string _scriptFoundByName;

        // Released DAVFX packs: display name (the store name), Asset Store package id, Fab listing id
        // ("" when not on Fab) and the GUIDs of the pack's root folder. A folder is a pack only if its GUID is listed,
        // so a customer's folder with the same name or a copy of the pack is never taken for it, and a renamed or
        // moved pack is still found. An entry without GUIDs falls back to a folder in Assets/DAVFX named exactly like the pack.
        private static readonly string[][] Released =
        {
            new[] { "Chromatic Aberration Distortion Pack", "408574", "", "65796fe916e508c4d82d18b36b24258f" },
            new[] { "Realistic 6D Lighting Aerial Explosions", "311624", "f34f9827-5f4b-4d0b-92c5-fb84492d4947", "55abe69d4a9ef08409aa29d9dee6deeb" },
            new[] { "Realistic 6D Lighting Explosions", "291615", "0de1d7b6-8621-4fee-b1c4-bea54391805b", "8a3565aee34a9804993dfe1f6ed49f7d" },
            new[] { "Realistic Decals Pack", "412620", "", "6e9aada313e9d90479a8ce86c5ac95ed" },
            new[] { "Realistic Impacts Pack", "368222", "", "543a0acc33df9484db3db0a6e89cfcf0" },
            new[] { "Realistic Muzzle Flashes Pack", "330624", "3a2209ed-2087-47bf-8601-be1b37c37aa6", "6f7664d4752a3f64599c1e60132325e1" },
            new[] { "Shader Graph Essential Subgraphs Pack", "333990", "b52944d0-d3a5-4cb8-8d26-2a7ff404fbdb", "f7d54e50eb326274da828dd5bad14f4a" },
            new[] { "VFX Essential Textures Pack", "400260", "", "7eea721e35419864d88050314c4286cd" },
        };
        public static readonly string[] Known = Array.ConvertAll(Released, r => r[0]);

        // used by the tests
        public static string[] KnownOverride = null;
        public static string[][] EntriesOverride = null;

        // the store icons (160x160 JPG), shown next to the pack names
        private static readonly string[][] Icons =
        {
            new[] { "Chromatic Aberration Distortion Pack",
                "" },
            new[] { "Realistic 6D Lighting Aerial Explosions",
                "" },
            new[] { "Realistic 6D Lighting Explosions",
                "" },
            new[] { "Realistic Decals Pack",
                "" },
            new[] { "Realistic Impacts Pack",
                "" },
            new[] { "Realistic Muzzle Flashes Pack",
                "" },
            new[] { "Shader Graph Essential Subgraphs Pack",
                "" },
            new[] { "VFX Essential Textures Pack",
                "" },
        };

        public static string IconData(string name)
        {
            if (string.IsNullOrEmpty(name)) return null;
            foreach (string[] r in Icons)
                if (string.Equals(r[0], name.Trim(), StringComparison.OrdinalIgnoreCase)) return r[1];
            return null;
        }

        // every copy of the script also keeps the union of all lists it has seen in EditorPrefs (outside the project),
        // so an older copy imported over a newer one still knows the packs released after it.
        public const string KnownKey = "DAVFX.GettingStarted.KnownPacks";
        public static string KnownKeyOverride = null;
        private static List<string[]> _all;
        private static readonly Regex StoreId = new Regex("^[0-9]{4,9}$");
        private static readonly Regex FabId = new Regex("^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$");
        private static readonly Regex GuidList = new Regex("^([0-9a-f]{32}(,[0-9a-f]{32}){0,31})?$");
        private const int MaxGuids = 32;

        public static void ResetCache() { _all = null; }

        private static bool ValidEntry(string[] r)
        {
            // a newer copy may add columns: they are kept as they are
            return r != null && r.Length >= 4 && ValidName(r[0])
                && (StoreId.IsMatch(r[1]) || (r[1].Length == 0 && FabId.IsMatch(r[2])))
                && (r[2].Length == 0 || FabId.IsMatch(r[2])) && GuidList.IsMatch(r[3]);
        }

        private static List<string[]> Entries()
        {
            if (EntriesOverride != null) return new List<string[]>(EntriesOverride);
            if (KnownOverride != null) return new List<string>(KnownOverride).ConvertAll(n => new[] { n, "", "", "" });
            if (_all != null) return _all;
            var list = new List<string[]>();
            foreach (string[] r in Released) list.Add((string[])r.Clone());
            try
            {
                string key = KnownKeyOverride ?? KnownKey;
                string raw = EditorPrefs.GetString(key, string.Empty);
                int read = 0;
                foreach (string line in raw.Split('\n'))
                {
                    if (++read > 200) break;
                    string[] parts = line.Split('\t');
                    if (!ValidEntry(parts)) continue;
                    string[] known = list.Find(r => string.Equals(r[0], parts[0], StringComparison.OrdinalIgnoreCase));
                    if (known == null) list.Add(parts);
                    else list[list.IndexOf(known)] = Merge(known, parts);
                }
                var lines = list.ConvertAll(r => string.Join("\t", r));
                string merged = string.Join("\n", lines.ToArray());
                if (merged != raw) EditorPrefs.SetString(key, merged);
            }
            catch
            {
            }
            return _all = list;
        }

        // the same pack seen by another copy of the script: keep the ids and GUIDs either copy knows
        private static string[] Merge(string[] known, string[] other)
        {
            string[] into = (string[])known.Clone();
            if (other.Length > into.Length)
            {
                Array.Resize(ref into, other.Length);
                Array.Copy(other, known.Length, into, known.Length, other.Length - known.Length);
            }
            if (into[1].Length == 0) into[1] = other[1];
            if (into[2].Length == 0) into[2] = other[2];
            var guids = new List<string>(into[3].Split(new[] { ',' }, StringSplitOptions.RemoveEmptyEntries));
            foreach (string g in other[3].Split(new[] { ',' }, StringSplitOptions.RemoveEmptyEntries))
                if (guids.Count < MaxGuids && !guids.Contains(g)) guids.Add(g);
            into[3] = string.Join(",", guids.ToArray());
            return into;
        }

        private static bool ValidName(string name)
        {
            if (string.IsNullOrEmpty(name) || name.Length > 80 || name.Trim() != name) return false;
            foreach (char c in name)
                if (char.IsControl(c) || c == '/' || c == '\\' || c == ':' || c == '*' || c == '?' || c == '"' || c == '<' || c == '>' || c == '|') return false;
            return true;
        }

        private static string[] Find(string name)
        {
            if (string.IsNullOrEmpty(name)) return null;
            string n = name.Trim().Normalize(System.Text.NormalizationForm.FormC);
            return Entries().Find(r => string.Equals(r[0].Normalize(System.Text.NormalizationForm.FormC), n, StringComparison.OrdinalIgnoreCase));
        }

        public static bool IsKnown(string name)
        {
            return Find(name) != null;
        }

        // the pack's Asset Store page, opened on the Reviews tab; null for an unknown pack
        public static string ReviewUrl(string name)
        {
            string[] r = Find(name);
            return r != null ? StoreUrl(r[1]) : null;
        }

        // the pack's Fab listing, null when it is not on Fab
        public static string FabUrl(string name)
        {
            string[] r = Find(name);
            return r != null ? FabListingUrl(r[2]) : null;
        }

        private static string StoreUrl(string id)
        {
            return StoreId.IsMatch(id) ? "https://assetstore.unity.com/packages/package/" + id + "#reviews" : null;
        }

        private static string FabListingUrl(string id)
        {
            return FabId.IsMatch(id) ? "https://www.fab.com/listings/" + id : null;
        }

        // "Demo", "Demos", "DemoScene", "demo_ground" match; "Demolition" does not
        private static readonly Regex DemoName = new Regex(@"(?:Demo|(?<![A-Za-z])demo)s?(?![a-z])|(?<![A-Za-z])DEMOS?(?![A-Za-z])");
        private static readonly string[] DocHints = { "read me", "readme", "read_me", "user guide", "documentation", "manual" };

        public static List<string> Roots()
        {
            var roots = new List<string>();
            if (!string.IsNullOrEmpty(RootOverride)) { roots.Add(RootOverride); return roots; }
            roots.Add(DefaultRoot);

            string folder = DavfxFolderOf(ScriptPath());
            if (folder == null) return roots;
            int same = roots.FindIndex(r => string.Equals(r, folder, StringComparison.OrdinalIgnoreCase));
            if (same < 0) roots.Add(folder);
            else if (roots[same] != folder)
            {
                // "Assets/davfx" vs "Assets/DAVFX": one folder, unless the file system is case-sensitive and both exist
                if (Array.IndexOf(AssetDatabase.GetSubFolders("Assets"), roots[same]) >= 0) roots.Add(folder);
                else roots[same] = folder;
            }
            return roots;
        }

        private static string ScriptPath()
        {
            string script = AssetDatabase.GUIDToAssetPath(ScriptGuid);
            if (!string.IsNullOrEmpty(script)) return script;

            // .meta regenerated by the customer: look the script up by name
            if (!string.IsNullOrEmpty(_scriptFoundByName) && AssetDatabase.LoadMainAssetAtPath(_scriptFoundByName) != null) return _scriptFoundByName;
            _scriptFoundByName = null;
            foreach (string g in AssetDatabase.FindAssets("DAVFXGettingStarted t:MonoScript"))
            {
                string c = AssetDatabase.GUIDToAssetPath(g);
                if (!string.IsNullOrEmpty(c) && c.EndsWith("/DAVFXGettingStarted.cs", StringComparison.OrdinalIgnoreCase)) return _scriptFoundByName = c;
            }
            return null;
        }

        private static string DavfxFolderOf(string script)
        {
            if (string.IsNullOrEmpty(script)) return null;
            string folder = Parent(script.Replace('\\', '/'));
            for (int up = 0; up < 2 && folder != null && !IsDavfxFolder(folder); up++) folder = Parent(folder);
            return folder != null && IsDavfxFolder(folder) ? folder : null;
        }

        private static string Parent(string path)
        {
            int slash = path.LastIndexOf('/');
            return slash > 0 ? path.Substring(0, slash) : null;
        }

        private static string NameOf(string path)
        {
            return path.Substring(path.LastIndexOf('/') + 1);
        }

        private static bool IsDavfxFolder(string folder)
        {
            return string.Equals(NameOf(folder), "DAVFX", StringComparison.OrdinalIgnoreCase);
        }

        public static List<PackEntry> FindAll()
        {
            var result = new List<PackEntry>();
            try
            {
                var added = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                List<string> roots = Roots();
                foreach (string[] r in Entries())
                {
                    foreach (string folder in FoldersOf(r, roots))
                    {
                        PackEntry pack = Detect(folder);
                        if (pack == null || pack.isEmpty || !added.Add(pack.folder)) continue;
                        pack.name = r[0];
                        pack.reviewUrl = StoreUrl(r[1]);
                        pack.fabUrl = FabListingUrl(r[2]);
                        result.Add(pack);
                    }
                }
                result.Sort((a, b) =>
                {
                    int c = string.Compare(a.name, b.name, StringComparison.OrdinalIgnoreCase);
                    return c != 0 ? c : string.CompareOrdinal(a.folder, b.folder);
                });
            }
            catch
            {
            }
            return result;
        }

        // the folders of the installed registered packs, without looking inside them
        public static List<string> PackFolders()
        {
            var all = new List<string>();
            try
            {
                List<string> roots = Roots();
                foreach (string[] r in Entries()) all.AddRange(FoldersOf(r, roots));
            }
            catch
            {
            }
            return all;
        }

        private static List<string> FoldersOf(string[] r, List<string> roots)
        {
            var folders = new List<string>();
            if (r[3].Length > 0)
            {
                foreach (string guid in r[3].Split(','))
                {
                    string path = AssetDatabase.GUIDToAssetPath(guid);
                    if (string.IsNullOrEmpty(path) || !AssetDatabase.IsValidFolder(path)) continue;
                    path = path.Replace('\\', '/');
                    bool inside = string.IsNullOrEmpty(RootOverride)
                        ? path.StartsWith("Assets/", StringComparison.Ordinal)
                        : path.StartsWith(RootOverride + "/", StringComparison.Ordinal);
                    if (inside) folders.Add(path);
                }
            }
            else
            {
                foreach (string root in roots)
                {
                    if (!AssetDatabase.IsValidFolder(root)) continue;
                    foreach (string sub in AssetDatabase.GetSubFolders(root))
                        if (!IsSpecialName(NameOf(sub).Trim()) && string.Equals(NameOf(sub).Trim().Normalize(System.Text.NormalizationForm.FormC),
                            r[0].Normalize(System.Text.NormalizationForm.FormC), StringComparison.OrdinalIgnoreCase)) folders.Add(sub);
                }
            }
            return folders;
        }

        // never a pack by its name alone; a pack found by its GUID is shown whatever its folder is called
        private static bool IsSpecialName(string name)
        {
            return name.Length == 0 || name.StartsWith("_", StringComparison.Ordinal) || name.StartsWith(".", StringComparison.Ordinal)
                || string.Equals(name, ToolFolderName, StringComparison.OrdinalIgnoreCase) || string.Equals(name, "Common", StringComparison.OrdinalIgnoreCase);
        }

        public static string PipelineOf(string folderName)
        {
            if (string.Equals(folderName, "HDRP", StringComparison.OrdinalIgnoreCase)) return "HDRP";
            if (string.Equals(folderName, "URP", StringComparison.OrdinalIgnoreCase)) return "URP";
            if (folderName.StartsWith("Built", StringComparison.OrdinalIgnoreCase) || string.Equals(folderName, "BiRP", StringComparison.OrdinalIgnoreCase)) return "Built-in";
            return string.Empty;
        }

        public static PackEntry Detect(string folder)
        {
            try
            {
                if (string.IsNullOrEmpty(folder) || !AssetDatabase.IsValidFolder(folder)) return null;
                folder = folder.Replace('\\', '/');
                string name = NameOf(folder).Trim();
                if (name.Length == 0) return null;

                var entry = new PackEntry { folder = folder, name = name, id = name };
                entry.folderGuid = AssetDatabase.AssetPathToGUID(folder);
                entry.docPath = FindDoc(folder);
                entry.scenes.AddRange(FindScenes(folder));
                FindHdrpPackage(entry);
                entry.isEmpty = IsEmptyFolder(folder);
                return entry;
            }
            catch
            {
                return null;
            }
        }

        // only folders and .meta files left, e.g. a pack whose content was deleted
        private static bool IsEmptyFolder(string folder)
        {
            try
            {
                string root = Path.GetFullPath(FileUtil.GetPhysicalPath(folder)).TrimEnd('/', '\\');
                foreach (string f in Directory.EnumerateFiles(root, "*", SearchOption.AllDirectories))
                {
                    if (Ignored(root, f)) continue;
                    return false;
                }
                return true;
            }
            catch
            {
                return false;
            }
        }

        // .meta files, anything Unity never imports (hidden names, names ending in "~", cvs, .tmp, and whatever is
        // inside such folders) and the files Windows leaves in folders
        private static bool Ignored(string root, string file)
        {
            string rel = Path.GetFullPath(file).Substring(root.Length).Replace('\\', '/');
            if (rel.EndsWith(".meta", StringComparison.OrdinalIgnoreCase) || rel.EndsWith(".tmp", StringComparison.OrdinalIgnoreCase)) return true;
            foreach (string seg in rel.Split(new[] { '/' }, StringSplitOptions.RemoveEmptyEntries))
                if (seg.StartsWith(".", StringComparison.Ordinal) || seg.EndsWith("~", StringComparison.Ordinal)
                    || string.Equals(seg, "cvs", StringComparison.OrdinalIgnoreCase)) return true;
            string name = Path.GetFileName(rel);
            return string.Equals(name, "Thumbs.db", StringComparison.OrdinalIgnoreCase) || string.Equals(name, "desktop.ini", StringComparison.OrdinalIgnoreCase);
        }

        private static int ComparePaths(string a, string b)
        {
            int c = string.Compare(a, b, StringComparison.OrdinalIgnoreCase);
            return c != 0 ? c : string.CompareOrdinal(a, b);
        }

        private static string Relative(string path, string folder)
        {
            return path.Length > folder.Length && path.StartsWith(folder, StringComparison.OrdinalIgnoreCase) ? path.Substring(folder.Length) : path;
        }

        public static bool IsDocFile(string path)
        {
            return !string.IsNullOrEmpty(path) && path.EndsWith(".pdf", StringComparison.OrdinalIgnoreCase);
        }

        public static bool Exists(string assetPath)
        {
            return !string.IsNullOrEmpty(assetPath) && !AssetDatabase.IsValidFolder(assetPath) && AssetDatabase.LoadMainAssetAtPath(assetPath) != null;
        }

        private static string FindDoc(string folder)
        {
            var pdfs = new List<string>();
            foreach (string guid in AssetDatabase.FindAssets(string.Empty, new[] { folder }))
            {
                string p = AssetDatabase.GUIDToAssetPath(guid);
                if (IsDocFile(p) && p.StartsWith(folder + "/", StringComparison.OrdinalIgnoreCase) && !pdfs.Contains(p)) pdfs.Add(p);
            }
            if (pdfs.Count == 0) return null;
            pdfs.Sort(ComparePaths);
            foreach (string hint in DocHints)
                foreach (string p in pdfs)
                    if (Path.GetFileNameWithoutExtension(p).IndexOf(hint, StringComparison.OrdinalIgnoreCase) >= 0) return p;
            return pdfs[0];
        }

        // HDRP content ships as a .unitypackage in <Pack>/HDRP, extracted by the customer
        private static void FindHdrpPackage(PackEntry entry)
        {
            string hdrp = null;
            foreach (string sub in AssetDatabase.GetSubFolders(entry.folder))
                if (PipelineOf(NameOf(sub)) == "HDRP") { hdrp = sub; break; }
            if (hdrp == null) return;

            var packages = new List<string>();
            bool other = false;
            try
            {
                string physical = Path.GetFullPath(FileUtil.GetPhysicalPath(hdrp)).TrimEnd('/', '\\');
                foreach (string f in Directory.EnumerateFiles(physical, "*", SearchOption.AllDirectories))
                {
                    if (Ignored(physical, f)) continue;
                    string n = Path.GetFileName(f);
                    if (n.EndsWith(".unitypackage", StringComparison.OrdinalIgnoreCase))
                        packages.Add(hdrp + Path.GetFullPath(f).Substring(physical.Length).Replace('\\', '/'));
                    else other = true;
                }
            }
            catch
            {
                return;
            }
            if (packages.Count == 0) return;
            packages.Sort(ComparePaths);
            entry.hdrpPackage = packages[0];
            entry.hdrpImported = other;
        }

        private static List<PackScene> FindScenes(string folder)
        {
            var all = new List<string>();
            foreach (string guid in AssetDatabase.FindAssets("t:SceneAsset", new[] { folder }))
            {
                string p = AssetDatabase.GUIDToAssetPath(guid);
                if (!string.IsNullOrEmpty(p) && p.StartsWith(folder + "/", StringComparison.OrdinalIgnoreCase)
                    && p.EndsWith(".unity", StringComparison.OrdinalIgnoreCase)) all.Add(p);
            }
            all.Sort(ComparePaths);

            // demo scenes only, never test or work scenes
            var paths = all.FindAll(p => DemoName.IsMatch(Relative(p, folder)));
            if (paths.Count > MaxScenes)
            {
                // keep the scenes that run in this project first
                string active = ActivePipeline();
                var first = paths.FindAll(p => { string sp = ScenePipeline(Relative(p, folder)); return sp.Length == 0 || sp == active; });
                first.AddRange(paths.FindAll(p => !first.Contains(p)));
                paths = first.GetRange(0, MaxScenes);
                paths.Sort(ComparePaths);
            }

            var scenes = new List<PackScene>();
            foreach (string p in paths)
                scenes.Add(new PackScene { path = p, pipeline = ScenePipeline(Relative(p, folder)) });

            // label: the pipeline when it is unique, otherwise the file name, plus the folder if that still clashes
            foreach (PackScene s in scenes)
            {
                if (scenes.Count == 1) s.label = string.Empty;
                else if (s.pipeline.Length > 0 && scenes.FindAll(o => o.pipeline == s.pipeline).Count == 1) s.label = s.pipeline;
                else s.label = Path.GetFileNameWithoutExtension(s.path);
            }
            var labels = scenes.ConvertAll(s => s.label);
            foreach (PackScene s in scenes)
                if (s.label.Length > 0 && labels.FindAll(l => l == s.label).Count > 1)
                    s.label += " (" + NameOf(Parent(s.path)) + ")";
            return scenes;
        }

        private static string ScenePipeline(string relativePath)
        {
            foreach (string seg in relativePath.Split('/'))
            {
                string p = PipelineOf(seg);
                if (p.Length > 0) return p;
            }
            return string.Empty;
        }

        public static string ActivePipeline()
        {
            var asset = UnityEngine.Rendering.GraphicsSettings.currentRenderPipeline;
            if (asset == null) return "Built-in";
            string type = asset.GetType().Name;
            if (type.StartsWith("HDRender", StringComparison.Ordinal)) return "HDRP";
            if (type.StartsWith("UniversalRender", StringComparison.Ordinal)) return "URP";
            return string.Empty;
        }
    }

    public static class Prefs
    {
        public static string TestPrefix = null;

        private static string _prefix;

        private static string Prefix
        {
            get
            {
                if (!string.IsNullOrEmpty(TestPrefix)) return TestPrefix;
                if (_prefix != null) return _prefix;
                string project = null;
                try
                {
                    Guid g = PlayerSettings.productGUID;
                    if (g != Guid.Empty) project = g.ToString("N");
                }
                catch { }
                if (project == null) project = StableHash(Application.dataPath);
                return _prefix = "DAVFX.GettingStarted." + project + ".";
            }
        }

        public static bool ShowOnImport
        {
            get { try { return EditorPrefs.GetBool(Prefix + "ShowOnImport", true); } catch { return true; } }
            set { try { EditorPrefs.SetBool(Prefix + "ShowOnImport", value); } catch { } }
        }

        public static bool HasUnseen(List<PackEntry> packs)
        {
            HashSet<string> seen = Seen();
            foreach (PackEntry p in packs)
                if (!seen.Contains(p.id) && !(!string.IsNullOrEmpty(p.folderGuid) && seen.Contains(GuidKey(p.folderGuid)))) return true;
            return false;
        }

        // the same test as HasUnseen, on the bare folders: a pack folder seen by name or by GUID counts as seen
        public static bool HasUnseenFolder(List<string> folders)
        {
            if (folders == null) return false;
            HashSet<string> seen = Seen();
            foreach (string f in folders)
            {
                string id = f.Substring(f.LastIndexOf('/') + 1).Trim();
                string guid = AssetDatabase.AssetPathToGUID(f);
                if (!seen.Contains(id) && !(!string.IsNullOrEmpty(guid) && seen.Contains(GuidKey(guid)))) return true;
            }
            return false;
        }

        public static void MarkSeen(List<PackEntry> packs)
        {
            try
            {
                HashSet<string> seen = Seen();
                bool changed = false;
                foreach (PackEntry p in packs)
                {
                    changed |= seen.Add(p.id);
                    if (!string.IsNullOrEmpty(p.folderGuid)) changed |= seen.Add(GuidKey(p.folderGuid));
                }
                if (changed) EditorPrefs.SetString(Prefix + "Seen", string.Join("\n", seen));
            }
            catch { }
        }

        // the folder GUID survives renames, moves and reinstalls
        private static string GuidKey(string folderGuid)
        {
            return "key:guid:" + folderGuid;
        }

        public static void Clear()
        {
            try
            {
                EditorPrefs.DeleteKey(Prefix + "Seen");
                EditorPrefs.DeleteKey(Prefix + "ShowOnImport");
            }
            catch { }
        }

        private static HashSet<string> Seen()
        {
            try
            {
                string raw = EditorPrefs.GetString(Prefix + "Seen", string.Empty);
                return new HashSet<string>(raw.Split(new[] { '\n' }, StringSplitOptions.RemoveEmptyEntries));
            }
            catch
            {
                return new HashSet<string>();
            }
        }

        private static string StableHash(string s)
        {
            uint h = 2166136261;
            foreach (char c in s ?? string.Empty) { h ^= c; h *= 16777619; }
            return h.ToString("x8");
        }
    }

    [InitializeOnLoad]
    public static class AutoOpen
    {
        static AutoOpen()
        {
            Schedule();
        }

        public static void Schedule()
        {
            try
            {
                if (Application.isBatchMode || AssetDatabase.IsAssetImportWorkerProcess() || IsProjectClone()) return;
                if (!string.IsNullOrEmpty(Prefs.TestPrefix)) return;
                EditorApplication.update -= Tick;
                EditorApplication.update += Tick;
            }
            catch { }
        }

        private static void Tick()
        {
            try
            {
                if (EditorApplication.isCompiling || EditorApplication.isUpdating) return;
                if (EditorApplication.isPlayingOrWillChangePlaymode) return;
                if (!string.IsNullOrEmpty(Prefs.TestPrefix)) return;
                EditorApplication.update -= Tick;

                // runs after every compile and import: look inside the packs only when one is new to this project
                if (!Prefs.HasUnseenFolder(PackRegistry.PackFolders())) return;
                List<PackEntry> packs = PackRegistry.FindAll();
                bool open = Prefs.ShowOnImport && ShouldOpen(packs);
                Prefs.MarkSeen(packs);
                // still unseen means the preferences are read-only: opening would repeat after every compile
                if (open && !ShouldOpen(packs)) GettingStartedWindow.Open();
            }
            catch
            {
                EditorApplication.update -= Tick;
            }
        }

        private static bool IsProjectClone()
        {
            string path = Application.dataPath;
            return !string.IsNullOrEmpty(path) && path.Replace('\\', '/').IndexOf("/Library/VP/", StringComparison.OrdinalIgnoreCase) >= 0;
        }

        // only registered DAVFX packs are ever listed, so every one of them may announce itself
        public static bool ShouldOpen(List<PackEntry> packs)
        {
            return packs != null && Prefs.HasUnseen(packs);
        }
    }

    // a second pack may ship the very same script, so there is no domain reload: watch the import instead
    public class ImportWatcher : AssetPostprocessor
    {
        private static void OnPostprocessAllAssets(string[] importedAssets, string[] deletedAssets, string[] movedAssets, string[] movedFromAssetPaths)
        {
            try
            {
                if (Touches(importedAssets) || Touches(movedAssets)) AutoOpen.Schedule();
            }
            catch { }
        }

        public static bool Touches(string[] paths)
        {
            if (paths == null) return false;
            bool anyRoot = !string.IsNullOrEmpty(PackRegistry.RootOverride);
            List<string> prefixes = null;
            string inside = (anyRoot ? PackRegistry.RootOverride : "Assets") + "/";
            foreach (string p in paths)
            {
                if (string.IsNullOrEmpty(p)) continue;
                // a pack always brings its folder, found by GUID even if the DAVFX folder was renamed or moved
                if (p.StartsWith(inside, StringComparison.OrdinalIgnoreCase) && AssetDatabase.IsValidFolder(p)) return true;
                if (!anyRoot && p.IndexOf("/DAVFX/", StringComparison.OrdinalIgnoreCase) < 0) continue;
                if (prefixes == null)
                {
                    prefixes = PackRegistry.Roots();
                    for (int i = 0; i < prefixes.Count; i++) prefixes[i] += "/";
                }
                foreach (string prefix in prefixes)
                    if (p.StartsWith(prefix, StringComparison.OrdinalIgnoreCase)) return true;
            }
            return false;
        }
    }

