        private const string LanguageKey = "DAVFX.GettingStarted.Language";

        private static int _cached = -1;

        public static int Language
        {
            get
            {
                if (_cached < 0)
                {
                    try { _cached = EditorPrefs.GetInt(LanguageKey, 0); } catch { _cached = 0; }
                    if (_cached < 0 || _cached >= Table.Length) _cached = 0;
                }
                return _cached;
            }
            set
            {
                _cached = value >= 0 && value < Table.Length ? value : 0;
                try { EditorPrefs.SetInt(LanguageKey, _cached); } catch { }
            }
        }

        public static void Reload() { _cached = -1; }

        public static string Get(int key)
        {
            string[] row = Table[Language];
            return key >= 0 && key < row.Length && !string.IsNullOrEmpty(row[key]) ? row[key] : Table[0][key];
        }
    }

