        private bool _unmarked;
        private DateTime _lastRefresh = DateTime.MinValue;
        private EditorApplication.CallbackFunction _deferred;

        [MenuItem("Window/DAVFX/Getting Started")]
        public static void Open()
        {
            try
            {
                bool wasOpen = HasOpenInstances<GettingStartedWindow>();
                var window = GetWindow<GettingStartedWindow>(false, "DAVFX", true);
                window.minSize = new Vector2(380, 360);
                if (!wasOpen && !window.docked) window.position = StartRect();
                if (EditorApplication.isCompiling || EditorApplication.isUpdating) window.RequestRefresh();
                else
                {
                    window.Refresh();
                    window.MarkShownPacks();
                }
                window.Show();
            }
            catch { }
        }

        // 440 x 640 in the middle of the editor, smaller if the editor is smaller
        private static Rect StartRect()
        {
            Rect main = EditorGUIUtility.GetMainWindowPosition();
            float w = Mathf.Min(440, Mathf.Max(380, main.width - 40));
            float h = Mathf.Min(640, Mathf.Max(360, main.height - 80));
            return new Rect(main.x + (main.width - w) * 0.5f, main.y + (main.height - h) * 0.5f, w, h);
        }

        private void OnEnable()
        {
            EditorApplication.playModeStateChanged -= OnPlayModeChanged;
            EditorApplication.playModeStateChanged += OnPlayModeChanged;
            titleContent = new GUIContent("DAVFX");
            _title = null;
            if (EditorApplication.isCompiling || EditorApplication.isUpdating) RequestRefresh();
            else
            {
                Refresh();
                if (_packs.Count == 0) RequestRefresh();
            }
        }

        private void OnDisable()
        {
            EditorApplication.playModeStateChanged -= OnPlayModeChanged;
            if (_deferred != null) EditorApplication.delayCall -= _deferred;
            DestroyArt();
        }

        private void OnPlayModeChanged(PlayModeStateChange change)
        {
            Repaint();
        }

        private void OnProjectChange()
        {
            RequestRefresh();
        }

        private void OnBecameVisible()
        {
            if ((DateTime.UtcNow - _lastRefresh).TotalSeconds > 2) RequestRefresh();
        }

        private void RequestRefresh()
        {
            _dirty = true;
            if (_deferred == null) _deferred = RunDeferredRefresh;
            EditorApplication.delayCall -= _deferred;
            EditorApplication.delayCall += _deferred;
        }

        private void RunDeferredRefresh()
        {
            try
            {
                if (!_dirty) return;
                double since = (DateTime.UtcNow - _lastRefresh).TotalSeconds;
                bool busy = EditorApplication.isCompiling || EditorApplication.isUpdating
                    || (since >= 0 && since < RefreshInterval);
                if (busy)
                {
                    RequestRefresh();
                    return;
                }
                Refresh();
                Repaint();
            }
            catch { }
        }

        public void Refresh()
        {
            _dirty = false;
            _lastRefresh = DateTime.UtcNow;
            _packs = PackRegistry.FindAll();
            _unmarked = _packs.Count > 0;
            try { _activePipeline = PackRegistry.ActivePipeline(); } catch { _activePipeline = string.Empty; }
        }

        public int PackCount { get { return _packs.Count; } }

        private void MarkShownPacks()
        {
            if (!_unmarked) return;
            _unmarked = false;
            Prefs.MarkSeen(_packs);
        }

        private void InitStyles()
        {
            bool pro = EditorGUIUtility.isProSkin;
            if (_title != null && _stylesPro == pro) return;
            _stylesPro = pro;

            var section = Flat(new GUIStyle(EditorStyles.boldLabel) { fontSize = 13 });
            var packName = Flat(new GUIStyle(EditorStyles.boldLabel) { fontSize = 13, wordWrap = true });
            var muted = Flat(new GUIStyle(EditorStyles.label) { wordWrap = true });
            muted.normal.textColor = pro ? new Color(0.70f, 0.70f, 0.70f) : new Color(0.25f, 0.25f, 0.25f);
            var mini = Flat(new GUIStyle(EditorStyles.miniLabel) { wordWrap = true });
            var title = Flat(new GUIStyle(EditorStyles.boldLabel) { fontSize = 18, alignment = TextAnchor.MiddleLeft });

            _page = new GUIStyle { padding = new RectOffset(12, 12, 0, 0) };
            _box = new GUIStyle(EditorStyles.helpBox) { margin = new RectOffset(0, 0, 0, 0), padding = new RectOffset(8, 8, 6, 6) };
            _button = new GUIStyle(GUI.skin.button) { margin = new RectOffset(0, 0, 0, 0) };
            _plain = new GUIStyle { margin = new RectOffset(0, 0, 0, 0), padding = new RectOffset(0, 0, 0, 0) };

            _section = section;
            _packName = packName;
            _muted = muted;
            _mini = mini;
            _title = title;
        }

        private static GUIStyle Flat(GUIStyle style)
        {
            style.margin = new RectOffset(0, 0, style.margin.top, style.margin.bottom);
            style.padding = new RectOffset(0, 0, style.padding.top, style.padding.bottom);
            return style;
        }

        private void EnsureArt()
        {
            float scale = Mathf.Clamp(EditorGUIUtility.pixelsPerPoint, 1f, 4f);
            bool pro = EditorGUIUtility.isProSkin;
            if (_logo != null && _iconChat != null && _iconMail != null && _iconWeb != null && _iconPacks != null
                && Mathf.Approximately(scale, _artScale) && pro == _artPro) return;
            DestroyArt();
            _artScale = scale;
            _artPro = pro;

            Color text = _title.normal.textColor;
            Color icon = GUI.skin.button.normal.textColor;
            int logoH = Mathf.RoundToInt(LogoHeight * scale);
            _logo = Art.Render(Mathf.RoundToInt(logoH * Art.LogoWidth / Art.LogoHeight), logoH, Art.LogoWidth, Art.LogoHeight, Art.Logo, text);
            int iconPx = Mathf.RoundToInt(IconSize * scale);
            _iconChat = Art.Render(iconPx, iconPx, 16, 16, Art.Chat, icon);
            _iconMail = Art.Render(iconPx, iconPx, 16, 16, Art.Mail, icon);
            _iconWeb = Art.Render(iconPx, iconPx, 16, 16, Art.Web, icon);
            _iconPacks = Art.FromEditorIcon("UnityLogo", iconPx, icon) ?? Art.Render(iconPx, iconPx, 16, 16, Art.Packs, icon);
        }

        private void DestroyArt()
        {
            Texture2D[] all = { _logo, _iconChat, _iconMail, _iconWeb, _iconPacks };
            foreach (Texture2D t in all)
                if (t != null) DestroyImmediate(t);
            _logo = _iconChat = _iconMail = _iconWeb = _iconPacks = null;
            foreach (Texture2D t in _packIcons.Values)
                if (t != null) DestroyImmediate(t);
            _packIcons.Clear();
        }

        private void OnGUI()
        {
            try
            {
                InitStyles();
                EnsureArt();
                if (_dirty) RequestRefresh();
                if (Event.current.type == EventType.Layout) _playing = EditorApplication.isPlayingOrWillChangePlaymode;
                List<PackEntry> packs = _packs;
                MarkShownPacks();

                using (var scroll = new EditorGUILayout.ScrollViewScope(_scroll))
                {
                    _scroll = scroll.scrollPosition;
                    using (new EditorGUILayout.VerticalScope(_page, GUILayout.ExpandWidth(true)))
                    {
                        GUILayout.Space(12);
                        DrawTitle();
                        GUILayout.Space(2);
                        GUILayout.Label(Texts.Get(Texts.Thanks), _muted);
                        GUILayout.Space(16);

                        GUILayout.Label(Texts.Get(Texts.Installed), _section);
                        GUILayout.Space(6);
                        if (packs.Count == 0)
                            GUILayout.Label(Texts.Get(Texts.NoPacks), _muted);
                        foreach (PackEntry pack in packs)
                            DrawPack(pack);

                        GUILayout.Space(10);
                        GUILayout.Label(Texts.Get(Texts.Community), _section);
                        GUILayout.Space(6);

                        EditorGUIUtility.SetIconSize(new Vector2(IconSize, IconSize));
                        try
                        {
                            int clicked = Buttons(26, 0, new GUIContent(" " + Texts.Get(Texts.Discord), _iconChat), new GUIContent(" " + Texts.Get(Texts.Email), _iconMail));
                            if (clicked == 0) OpenUrl(DiscordUrl);
                            if (clicked == 1) OpenUrl("mailto:" + SupportEmail);
                            GUILayout.Space(Gap);
                            clicked = Buttons(26, 0, new GUIContent(" " + Texts.Get(Texts.Website), _iconWeb), new GUIContent(" " + Texts.Get(Texts.MorePacks), _iconPacks));
                            if (clicked == 0) OpenUrl(WebsiteUrl);
                            if (clicked == 1) OpenUrl(PublisherUrl);
                        }
                        finally
                        {
                            EditorGUIUtility.SetIconSize(Vector2.zero);
                        }

                        GUILayout.Space(6);
                        Rect mail = GUILayoutUtility.GetRect(new GUIContent(SupportEmail), _muted, GUILayout.Height(EditorGUIUtility.singleLineHeight));
                        EditorGUI.SelectableLabel(mail, SupportEmail, _muted);

                        GUILayout.Space(12);
                    }
                }

                DrawLine();
                using (new EditorGUILayout.VerticalScope(_page))
                {
                    GUILayout.Space(4);
                    bool show = Prefs.ShowOnImport;
                    string toggleText = Texts.Get(Texts.ShowOnImport);
                    Rect toggle = GUILayoutUtility.GetRect(new GUIContent(toggleText), EditorStyles.toggle, GUILayout.Height(EditorGUIUtility.singleLineHeight), GUILayout.ExpandWidth(true));
                    bool newShow = EditorGUI.ToggleLeft(toggle, toggleText, show);
                    if (newShow != show) Prefs.ShowOnImport = newShow;
                    GUILayout.Label(Texts.Get(Texts.Reopen), _mini);
                    GUILayout.Space(6);
                }
            }
            catch (ExitGUIException)
            {
                throw;
            }
            catch
            {
            }
        }

        private void DrawTitle()
        {
            Rect row = GUILayoutUtility.GetRect(GUIContent.none, _plain, GUILayout.Height(LogoHeight), GUILayout.ExpandWidth(true));
            float logoW = LogoHeight * Art.LogoWidth / Art.LogoHeight;
            if (_logo != null && Event.current.type == EventType.Repaint)
                GUI.DrawTexture(new Rect(row.x, row.y, logoW, LogoHeight), _logo, ScaleMode.StretchToFill, true);
            const float popupWidth = 100;
            GUI.Label(new Rect(row.x + logoW + 8, row.y, row.width - logoW - 8 - popupWidth - Gap, LogoHeight), "DAVFX", _title);
            Rect popup = new Rect(row.xMax - popupWidth, row.y + (LogoHeight - EditorGUIUtility.singleLineHeight) * 0.5f, popupWidth, EditorGUIUtility.singleLineHeight);
            int language = Texts.Language;
            int chosen = EditorGUI.Popup(popup, language, Texts.Languages);
            if (chosen != language)
            {
                Texts.Language = chosen;
                Repaint();
                GUIUtility.ExitGUI();
            }
        }

        private int Buttons(float height, float inset, params GUIContent[] buttons)
        {
            float available = position.width - _page.padding.horizontal - inset - ScrollbarWidth;
            float each = (available - Gap * (buttons.Length - 1)) / Mathf.Max(1, buttons.Length);
            bool fits = true;
            foreach (GUIContent b in buttons)
                if (_button.CalcSize(b).x > each) fits = false;
            if (fits || buttons.Length < 2) return ButtonRow(height, buttons);
            int clicked = -1;
            for (int i = 0; i < buttons.Length; i++)
            {
                if (i > 0) GUILayout.Space(Gap);
                if (ButtonRow(height, buttons[i]) == 0) clicked = i;
            }
            return clicked;
        }

        private int ButtonRow(float height, params GUIContent[] buttons)
        {
            Rect row = GUILayoutUtility.GetRect(GUIContent.none, _plain, GUILayout.Height(height), GUILayout.ExpandWidth(true));
            int clicked = -1;
            if (buttons.Length == 0) return clicked;
            float width = (row.width - Gap * (buttons.Length - 1)) / buttons.Length;
            for (int i = 0; i < buttons.Length; i++)
            {
                float x = Mathf.Round(row.x + i * (width + Gap));
                float right = i == buttons.Length - 1 ? row.xMax : Mathf.Round(row.x + i * (width + Gap) + width);
                if (GUI.Button(new Rect(x, row.y, right - x, height), buttons[i], _button)) clicked = i;
            }
            return clicked;
        }

        private void DrawPack(PackEntry pack)
        {
            using (new EditorGUILayout.VerticalScope(_box))
            {
                DrawPackName(pack);
                GUILayout.Space(6);

                // HDRP project with the HDRP version still packed: say how to get it before anything else
                if (_activePipeline == "HDRP" && pack.hdrpPackage != null && !pack.hdrpImported)
                {
                    string file = Path.GetFileName(pack.hdrpPackage);
                    GUILayout.Label(string.Format(Texts.Get(Texts.HdrpNote), file), _muted);
                    GUILayout.Space(Gap);
                    string package = pack.hdrpPackage;
                    if (ButtonRow(24, new GUIContent(Texts.Get(Texts.ShowHdrpPackage))) == 0) Ping(package);
                    GUILayout.Space(Gap + 2);
                }

                using (new EditorGUI.DisabledScope(_playing))
                {
                    Color background = GUI.backgroundColor;
                    try
                    {
                        foreach (PackScene scene in pack.scenes)
                        {
                            // green unless the scene needs another render pipeline
                            bool other = scene.pipeline.Length > 0 && _activePipeline.Length > 0 && scene.pipeline != _activePipeline;
                            GUI.backgroundColor = other ? background : (EditorGUIUtility.isProSkin ? new Color(0.55f, 0.95f, 0.62f) : new Color(0.68f, 1f, 0.72f));
                            string detail = scene.label;
                            if (other)
                            {
                                string requires = string.Format(Texts.Get(Texts.Requires), scene.pipeline);
                                detail = detail.Length == 0 || detail == scene.pipeline ? requires : detail + ", " + requires;
                            }
                            string label = Texts.Get(Texts.OpenDemo) + (detail.Length > 0 ? " (" + detail + ")" : string.Empty);
                            string path = scene.path;
                            if (ButtonRow(24, new GUIContent(label, scene.path)) == 0)
                                EditorApplication.delayCall += () => OpenScene(path);
                            GUILayout.Space(Gap);
                        }
                    }
                    finally
                    {
                        GUI.backgroundColor = background;
                    }
                }
                if (_playing && pack.scenes.Count > 0)
                {
                    GUILayout.Label(Texts.Get(Texts.ExitPlayMode), _mini);
                    GUILayout.Space(Gap);
                }

                var actions = new List<GUIContent>();
                bool hasDoc = pack.docPath != null;
                if (hasDoc) actions.Add(new GUIContent(Texts.Get(Texts.Documentation)));
                actions.Add(new GUIContent(Texts.Get(Texts.ShowInProject)));
                actions.Add(new GUIContent(Texts.Get(Texts.Review)));
                int clicked = Buttons(22, _box.padding.horizontal, actions.ToArray());
                if (!hasDoc && clicked >= 0) clicked++;
                if (clicked == 0)
                {
                    string doc = pack.docPath;
                    EditorApplication.delayCall += () => OpenFile(doc);
                }
                else if (clicked == 1) Ping(pack.folder);
                else if (clicked == 2) Review(pack);
            }
            GUILayout.Space(Gap + 2);
        }

        private Texture2D PackIcon(string name)
        {
            Texture2D cached;
            if (_packIcons.TryGetValue(name, out cached) && cached != null) return cached;
            if (_badIcons.Contains(name)) return null;
            string data = PackRegistry.IconData(name);
            if (data == null) return null;
            Texture2D tex = null;
            try
            {
                tex = new Texture2D(2, 2, TextureFormat.RGB24, false) { hideFlags = HideFlags.HideAndDontSave, wrapMode = TextureWrapMode.Clamp, filterMode = FilterMode.Bilinear };
                if (!tex.LoadImage(Convert.FromBase64String(data)))
                {
                    DestroyImmediate(tex);
                    _badIcons.Add(name);
                    return null;
                }
                _packIcons[name] = tex;
                return tex;
            }
            catch
            {
                if (tex != null) DestroyImmediate(tex);
                _badIcons.Add(name);
                return null;
            }
        }

        // pack thumbnail (Unity logo when there is none) in front of the name, both centered on the row
        private void DrawPackName(PackEntry pack)
        {
            const float pad = 8;
            Texture2D thumb = PackIcon(pack.name);
            Texture2D icon = thumb != null ? thumb : _iconPacks;
            float size = thumb != null ? PackIconSize : IconSize;
            float iconW = icon != null ? size + pad : 0;
            float width = Mathf.Max(40, position.width - _page.padding.horizontal - _box.padding.horizontal - ScrollbarWidth - iconW);
            var content = new GUIContent(pack.name);
            float textH = _packName.CalcHeight(content, width);
            float height = Mathf.Max(size, textH);
            Rect row = GUILayoutUtility.GetRect(GUIContent.none, _plain, GUILayout.Height(height), GUILayout.ExpandWidth(true));
            if (icon != null && Event.current.type == EventType.Repaint)
            {
                var r = new Rect(row.x, row.y + (height - size) * 0.5f, size, size);
                if (thumb != null) GUI.DrawTexture(r, thumb, ScaleMode.ScaleToFit, false, 0, Color.white, 0, 3);
                else GUI.DrawTexture(r, icon, ScaleMode.ScaleToFit, true);
            }
            GUI.Label(new Rect(row.x + iconW, row.y + (height - textH) * 0.5f, row.width - iconW, textH), content, _packName);
        }

        // on Fab too: let the customer pick the store they bought it from
        private static void Review(PackEntry pack)
        {
            if (pack.fabUrl == null || pack.reviewUrl == null)
            {
                OpenUrl(pack.reviewUrl ?? pack.fabUrl ?? PublisherUrl);
                return;
            }
            string store = pack.reviewUrl;
            string fab = pack.fabUrl;
            var menu = new GenericMenu();
            menu.AddItem(new GUIContent("Unity Asset Store"), false, () => OpenUrl(store));
            menu.AddItem(new GUIContent("Fab"), false, () => OpenUrl(fab));
            menu.ShowAsContext();
        }

        private static void DrawLine()
        {
            Rect r = GUILayoutUtility.GetRect(1, 1, GUILayout.ExpandWidth(true));
            EditorGUI.DrawRect(r, EditorGUIUtility.isProSkin ? new Color(1f, 1f, 1f, 0.1f) : new Color(0f, 0f, 0f, 0.15f));
        }

        private static void OpenUrl(string url)
        {
            try { Application.OpenURL(url); } catch { }
        }

        public static void OpenScene(string path)
        {
            try
            {
                if (EditorApplication.isPlayingOrWillChangePlaymode || EditorApplication.isCompiling || EditorApplication.isUpdating) return;
                if (string.IsNullOrEmpty(path) || AssetDatabase.LoadAssetAtPath<SceneAsset>(path) == null) return;

                if (PrefabStageUtility.GetCurrentPrefabStage() != null)
                {
                    UnityEditor.SceneManagement.StageUtility.GoToMainStage();
                    if (PrefabStageUtility.GetCurrentPrefabStage() != null) return;
                }

                if (!EditorSceneManager.SaveCurrentModifiedScenesIfUserWantsTo()) return;
                EditorSceneManager.OpenScene(path, OpenSceneMode.Single);
            }
            catch { }
        }

        public static void OpenFile(string assetPath)
        {
            try
            {
                if (!PackRegistry.IsDocFile(assetPath) || !PackRegistry.Exists(assetPath)) return;
                string full = Path.GetFullPath(FileUtil.GetPhysicalPath(assetPath));
                if (File.Exists(full)) EditorUtility.OpenWithDefaultApp(full);
            }
            catch { }
        }

        private static void Ping(string assetPath)
        {
            try
            {
                UnityEngine.Object obj = AssetDatabase.LoadMainAssetAtPath(assetPath);
                if (obj == null) return;
                Selection.activeObject = obj;
                EditorGUIUtility.PingObject(obj);
            }
            catch (ExitGUIException)
            {
                throw;
            }
            catch { }
        }
    }
    // logo and icons drawn in code, no image files
    public static class Art
    {
        public const float LogoWidth = 253f, LogoHeight = 281f;

        private static readonly Vector2[] LogoOuter =
        {
            new Vector2(0, 0), new Vector2(185, 0), new Vector2(253, 67), new Vector2(253, 215),
            new Vector2(187, 281), new Vector2(52, 281), new Vector2(52, 230), new Vector2(0, 230)
        };
        private static readonly Vector2[] LogoInner =
        {
            new Vector2(52, 52), new Vector2(202, 52), new Vector2(202, 178), new Vector2(150, 230), new Vector2(52, 230)
        };

        private const float Stroke = 1.35f;
        private static readonly Vector2[] Bubble = BubblePath();
        private static readonly Vector2[] Envelope = RoundRect(1.5f, 3.5f, 14.5f, 12.5f, 1.5f);
        private static readonly Vector2[] Flap = { new Vector2(2.2f, 4.6f), new Vector2(8f, 8.9f), new Vector2(13.8f, 4.6f) };
        private static readonly Vector2[] Meridian = Ellipse(8f, 8f, 2.8f, 6.3f);
        private static readonly Vector2[][] Squares =
        {
            RoundRect(2f, 2f, 7f, 7f, 1f), RoundRect(9f, 2f, 14f, 7f, 1f),
            RoundRect(2f, 9f, 7f, 14f, 1f), RoundRect(9f, 9f, 14f, 14f, 1f)
        };

        public static bool Logo(float x, float y) { return Inside(LogoOuter, x, y) != Inside(LogoInner, x, y); }

        public static bool Chat(float x, float y)
        {
            if (NearPath(Bubble, true, x, y, Stroke)) return true;
            for (int i = 0; i < 3; i++)
                if (Sq(x - (5f + 3f * i), y - 6.9f) <= 0.95f * 0.95f) return true;
            return false;
        }

        public static bool Mail(float x, float y)
        {
            return NearPath(Envelope, true, x, y, Stroke) || NearPath(Flap, false, x, y, Stroke);
        }

        public static bool Web(float x, float y)
        {
            float r = Mathf.Sqrt(Sq(x - 8f, y - 8f));
            if (Mathf.Abs(r - 6.3f) <= Stroke * 0.5f) return true;
            if (r > 6.3f) return false;
            return NearPath(Meridian, true, x, y, Stroke) || Mathf.Abs(y - 8f) <= Stroke * 0.5f;
        }

        public static bool Packs(float x, float y)
        {
            foreach (Vector2[] square in Squares)
                if (NearPath(square, true, x, y, Stroke)) return true;
            return false;
        }

        public static Texture2D Render(int width, int height, float designW, float designH, Func<float, float, bool> inside, Color color)
        {
            width = Mathf.Max(1, width);
            height = Mathf.Max(1, height);
            var pixels = new Color32[width * height];
            const int n = 4;
            for (int py = 0; py < height; py++)
                for (int px = 0; px < width; px++)
                {
                    int hits = 0;
                    for (int sy = 0; sy < n; sy++)
                        for (int sx = 0; sx < n; sx++)
                        {
                            float x = (px + (sx + 0.5f) / n) / width * designW;
                            float y = (py + (sy + 0.5f) / n) / height * designH;
                            if (inside(x, y)) hits++;
                        }
                    Color c = color;
                    c.a *= hits / (float)(n * n);
                    pixels[(height - 1 - py) * width + px] = c;
                }
            var texture = new Texture2D(width, height, TextureFormat.RGBA32, false)
            {
                hideFlags = HideFlags.HideAndDontSave,
                filterMode = FilterMode.Bilinear,
                wrapMode = TextureWrapMode.Clamp
            };
            texture.SetPixels32(pixels);
            texture.Apply(false, true);
            return texture;
        }

        public static Texture2D FromEditorIcon(string name, int size, Color color)
        {
            RenderTexture previous = RenderTexture.active;
            RenderTexture rt = null;
            Texture2D copy = null, texture = null;
            try
            {
                Texture2D source = EditorGUIUtility.FindTexture(name);
                if (source == null || source.width < 8 || source.height < 8) return null;
                rt = RenderTexture.GetTemporary(source.width, source.height, 0, RenderTextureFormat.ARGB32, RenderTextureReadWrite.Linear);
                Graphics.Blit(source, rt);
                RenderTexture.active = rt;
                copy = new Texture2D(source.width, source.height, TextureFormat.RGBA32, false) { hideFlags = HideFlags.HideAndDontSave };
                copy.ReadPixels(new Rect(0, 0, source.width, source.height), 0, 0, false);
                copy.Apply(false, false);
                RenderTexture.active = previous;

                size = Mathf.Max(1, size);
                var pixels = new Color32[size * size];
                const int n = 4;
                for (int py = 0; py < size; py++)
                    for (int px = 0; px < size; px++)
                    {
                        float alpha = 0f;
                        for (int sy = 0; sy < n; sy++)
                            for (int sx = 0; sx < n; sx++)
                                alpha += copy.GetPixelBilinear((px + (sx + 0.5f) / n) / size, (py + (sy + 0.5f) / n) / size).a;
                        Color c = color;
                        c.a *= alpha / (n * n);
                        pixels[py * size + px] = c;
                    }
                texture = new Texture2D(size, size, TextureFormat.RGBA32, false)
                {
                    hideFlags = HideFlags.HideAndDontSave,
                    filterMode = FilterMode.Bilinear,
                    wrapMode = TextureWrapMode.Clamp
                };
                texture.SetPixels32(pixels);
                texture.Apply(false, true);
                return texture;
            }
            catch
            {
                if (texture != null) UnityEngine.Object.DestroyImmediate(texture);
                return null;
            }
            finally
            {
                RenderTexture.active = previous;
                if (rt != null) RenderTexture.ReleaseTemporary(rt);
                if (copy != null) UnityEngine.Object.DestroyImmediate(copy);
            }
        }

        private static float Sq(float a, float b) { return a * a + b * b; }

        private static bool Inside(Vector2[] polygon, float x, float y)
        {
            bool inside = false;
            for (int i = 0, j = polygon.Length - 1; i < polygon.Length; j = i++)
            {
                Vector2 a = polygon[i], b = polygon[j];
                if ((a.y > y) != (b.y > y) && x < (b.x - a.x) * (y - a.y) / (b.y - a.y) + a.x) inside = !inside;
            }
            return inside;
        }

        private static bool NearPath(Vector2[] path, bool closed, float x, float y, float width)
        {
            float limit = width * 0.5f * width * 0.5f;
            int count = closed ? path.Length : path.Length - 1;
            for (int i = 0; i < count; i++)
            {
                Vector2 a = path[i], b = path[(i + 1) % path.Length];
                Vector2 ab = b - a;
                float t = ab.sqrMagnitude > 0f ? Mathf.Clamp01(((x - a.x) * ab.x + (y - a.y) * ab.y) / ab.sqrMagnitude) : 0f;
                if (Sq(x - (a.x + ab.x * t), y - (a.y + ab.y * t)) <= limit) return true;
            }
            return false;
        }

        private static Vector2[] RoundRect(float x0, float y0, float x1, float y1, float r)
        {
            var points = new List<Vector2>();
            AddArc(points, x1 - r, y0 + r, r, -90f, 0f);
            AddArc(points, x1 - r, y1 - r, r, 0f, 90f);
            AddArc(points, x0 + r, y1 - r, r, 90f, 180f);
            AddArc(points, x0 + r, y0 + r, r, 180f, 270f);
            return points.ToArray();
        }

        private static Vector2[] BubblePath()
        {
            const float x0 = 1.5f, y0 = 2f, x1 = 14.5f, y1 = 11.5f, r = 2.5f;
            var points = new List<Vector2>();
            AddArc(points, x1 - r, y0 + r, r, -90f, 0f);
            AddArc(points, x1 - r, y1 - r, r, 0f, 90f);
            points.Add(new Vector2(8f, y1));
            points.Add(new Vector2(4.6f, 14.6f));
            points.Add(new Vector2(4.6f, y1));
            AddArc(points, x0 + r, y1 - r, r, 90f, 180f);
            AddArc(points, x0 + r, y0 + r, r, 180f, 270f);
            return points.ToArray();
        }

        private static Vector2[] Ellipse(float cx, float cy, float rx, float ry)
        {
            var points = new Vector2[40];
            for (int i = 0; i < points.Length; i++)
            {
                float a = i * Mathf.PI * 2f / points.Length;
                points[i] = new Vector2(cx + Mathf.Cos(a) * rx, cy + Mathf.Sin(a) * ry);
            }
            return points;
        }

        private static void AddArc(List<Vector2> points, float cx, float cy, float r, float from, float to)
        {
            const int steps = 6;
            for (int i = 0; i <= steps; i++)
            {
                float a = Mathf.Deg2Rad * Mathf.Lerp(from, to, i / (float)steps);
                points.Add(new Vector2(cx + Mathf.Cos(a) * r, cy + Mathf.Sin(a) * r));
            }
        }
    }
}
#endif
